// Use this file to overwrite the basic Bootstrap variables and add your own variables
// To overwrite a Bootstrap variable you don´t have to touch the Bootstrap folder. 
// Just copy a variable from /sass/bootstrap/_variables.scss, paste it here and edit the value.
// As example you find one of the most important Bootstrap variable below: $brand-primary.
// Thats the ugly Bootstrap blue used for all the links, primary buttons etc.
// Just add your color code here, compile the theme.scss file to change this color everywhere


//Container Width
$container-width : rem(1180);

// Colors
$primary: #13568b;
$secondary: #0072bb;

$white: #fff;
$black: #000;
$blue: #0072bb;
$light-blue: #10b1d7;
$medium-blue: #28628F;
$lighter-blue: #0171bb;
$lightest-blue: #EFF4F8;
$dark-blue: #00334D;
$dark-grey: #212121;
$medium-gray: #666;
$medium-md-gray: #6d6d6d;
$gray: #444;
$light-gray: #f7f7f7;
$lighter-gray: #efefef;
$light-gray2:#E6EBF0;
$light-gray3: #EBEBEB;
$orange: #d95000;
$green: #62A139;
$medium-green: #6CB33F;
$off-black: #1C1C1C;

// PDF Modular Website Design Tokens
$pdf-container-width: rem(1180);
$pdf-gutter: rem(20);
$pdf-section-padding-y: rem(100);
$pdf-section-padding-y-md: rem(72);
$pdf-section-padding-y-sm: rem(56);
$pdf-radius-sm: rem(3);

$pdf-color-primary: #A91C23;
$pdf-color-primary-dark: #731219;
$pdf-color-surface: $white;
$pdf-color-surface-muted: #F5F7F8;
$pdf-color-surface-cool: #E6E9EC;
$pdf-color-surface-blue-gray: #C1CAD1;
$pdf-color-footer-bottom: #191919;
$pdf-color-footer-muted: #9EA4A9;
$pdf-color-cert-blue: #1F5F8F;
$pdf-color-cert-gold: #E0A51B;
$pdf-color-text: $black;
$pdf-color-text-muted: #444;
$pdf-color-on-dark: $white;

$pdf-font-family: 'Open Sans', sans-serif;
$pdf-heading-size: rem(36);
$pdf-heading-line-height: rem(48);
$pdf-heading-size-sm: rem(30);
$pdf-heading-line-height-sm: rem(38);
$pdf-heading-weight: 600;
$pdf-body-size: rem(16);
$pdf-body-line-height: rem(24);
$pdf-body-weight: 400;
$pdf-body-bold-weight: 700;
$pdf-card-title-size: rem(24);
$pdf-card-title-line-height: rem(32);
$pdf-card-title-weight: 600;
$pdf-link-size: rem(18);
$pdf-link-line-height: rem(24);
$pdf-link-weight: 600;
$pdf-button-size: rem(16);
$pdf-button-line-height: rem(24);
$pdf-button-size-lg: rem(21);
$pdf-button-line-height-lg: rem(28);
$pdf-footer-size: rem(15);
$pdf-footer-line-height: rem(24);
$pdf-footer-bottom-size: rem(14);
$pdf-footer-bottom-line-height: rem(20);
//Body Variables
$body-bg : $white;
$body-color: $dark-grey;


// Link Colors
$link-color: $light-blue;
$link-decoration: none;
$link-hover-color: $blue;
$link-hover-decoration: none;


// Typography
$font-family-base: 			  'Open Sans', sans-serif;
$font-size-base:              1rem !default; // Assumes the browser default, typically `16px`
$font-size-lg:                $font-size-base * 1.25 !default;
$font-size-sm:                $font-size-base * .875 !default;
$body-font-size:			  rem(18);

$font-weight-lighter:         lighter !default;
$font-weight-light:           300 !default;
$font-weight-normal:          400 !default;
$font-weight-bold:            700 !default;
$font-weight-bolder:          bolder !default;

$font-weight-base:            $font-weight-normal !default;
$line-height-base:            1.5625 !default;

$h1-font-size:                $font-size-base * 2.5 !default;
$h2-font-size:                rem(30) !default;
$h3-font-size:                rem(24) !default;
$h4-font-size:                rem(20) !default;
$h5-font-size:                rem(19) !default;
$h6-font-size:                $font-size-base !default;

$headings-font-family:        'Poppins', sans-serif !default;
$headings-font-weight:        700 !default;
$headings-line-height:        1.2 !default;
$headings-color:              $primary !default;

$display1-size:               6rem !default;
$display2-size:               5.5rem !default;
$display3-size:               4.5rem !default;
$display4-size:               3.5rem !default;

$display1-weight:             300 !default;
$display2-weight:             300 !default;
$display3-weight:             300 !default;
$display4-weight:             300 !default;
$display-line-height:         $headings-line-height !default;

$lead-font-size:              $font-size-base * 1.25 !default;
$lead-font-weight:            300 !default;

$small-font-size:             80% !default;

$blockquote-small-font-size:  $small-font-size !default;
$blockquote-font-size:        $font-size-base * 1.25 !default;

/*Navigation Variables*/
$nav-color: $black;
$nav-hover-color: $blue;
$nav-spacing: rem(16.5) rem(20);
$nav-font-size: rem(17);
$nav-font-weight: 600;

/*Darkbg color menu variables*/
$navbar-dark-nav-color: $white;
$navbar-dark-nav-hover-color: $black;

$nav-subnav-width: rem(343);
$nav-subnav-radius: 0;
$nav-subnav-color: $black;
$nav-subnav-bg-color: $light-gray;
$nav-subnav-hover-color: $white;
$nav-subnav-hover-bg-color: $blue;
$nav-subnav-font-size: rem(17);
$nav-subnav-font-weight: 600;
$nav-subnav-spacing: rem(16.5) rem(20);

/*============= Navigation Variables Mobile ==========*/
$nav-spacing-mobile: rem(8.5) rem(50) rem(8.5) rem(30);
$nav-subnav-spacing-mobile: rem(8.5) rem(50) rem(8.5) rem(60);
$nav-sub-subnav-spacing-left-mobile: rem(80);
$nav-sub-sub-subnav-spacing-left-mobile: rem(100);

/*============= TopLine Menu ==============*/
$topnav-color: $white;
$topnav-color-hover: $white;
$topnav-spacing: 0 rem(20);
$topnav-font-size: rem(17);
